import * as ort from 'onnxruntime-web';

let sessions = {
  ai1: null,
  ai2: null,
};

/**
 * ONNX 모델을 로드하고 예측 결과(0~17)를 반환
 * @param {number[]} inputArray - 길이 12의 숫자 배열
 * @param {"ai1" | "ai2"} aiType - 사용할 AI 모델 종류
 * @returns {Promise<number>} 예측된 행동 인덱스 (0~17)
 */
export async function predict(inputArray, aiType) {
  if (!sessions[aiType]) {
    sessions[aiType] = await ort.InferenceSession.create(`/resources/model/pikachu_${aiType}.onnx`);
  }

  const tensor = new ort.Tensor('float32', Float32Array.from(inputArray), [1, 12]);
  const feeds = {};
  feeds[sessions[aiType].inputNames[0]] = tensor;

  const results = await sessions[aiType].run(feeds);
  const output = results[sessions[aiType].outputNames[0]].data;

  const predicted = output.indexOf(Math.max(...output));
  return predicted;
}
